public sealed class PublicationUpstreamException(int statusCode,string code,string message,Exception? inner=null):Exception(message,inner){public int StatusCode{get;}=statusCode;public string DiagnosticCode{get;}=code;}

public sealed class AnalysisPublicationClient(HttpClient client)
{
 public async Task<AnalysisPackageDocument> GetPackageAsync(Guid fieldId,CancellationToken ct)
 {
  try{using var response=await client.GetAsync($"api/fields/{fieldId:D}/package",ct);if(!response.IsSuccessStatusCode)Throw(response.StatusCode,"PublicationPackageUnavailable","Analysis package read failed.");return await response.Content.ReadFromJsonAsync<AnalysisPackageDocument>(CanonicalJson.SerializerOptions,ct)??throw new PublicationUpstreamException(502,"PublicationPackageMalformed","Analysis package was empty.");}
  catch(PublicationUpstreamException){throw;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new PublicationUpstreamException(503,"PublicationPackageTimeout","Analysis package read timed out.");}catch(JsonException e){throw new PublicationUpstreamException(409,"PublicationPackageMalformed","Analysis package JSON was malformed.",e);}catch(HttpRequestException e){throw new PublicationUpstreamException(503,"PublicationPackageUnavailable","Analysis package is unavailable.",e);}
 }
 static void Throw(HttpStatusCode status,string code,string message)=>throw new PublicationUpstreamException((int)status>=500?503:409,code,message);
}
