public sealed partial class AnalysisRevealClient(HttpClient client)
{
 public Task<string> PrepareAsync(string scenarioId,AnalysisRevealRequest request,CancellationToken ct)=>SendAsync($"internal/scenarios/{Uri.EscapeDataString(scenarioId)}/reveal/prepare",request,scenarioId,request,"Prepared",ct);
 public Task<string> FinalizeAsync(string scenarioId,AnalysisRevealRequest expected,CancellationToken ct)=>SendAsync($"internal/scenarios/{Uri.EscapeDataString(scenarioId)}/reveal/finalize",new AnalysisFinalizeRequest(expected.RevealId,expected.ManifestSha256),scenarioId,expected,"Revealed",ct);
 public Task<string> BackfillSnapshotAsync(string scenarioId,AnalysisRevealRequest request,CancellationToken ct)=>SendAsync($"internal/scenarios/{Uri.EscapeDataString(scenarioId)}/reveal/snapshot/backfill",request,scenarioId,request,"Revealed",ct);
 async Task<string> SendAsync<T>(string route,T body,string scenarioId,AnalysisRevealRequest expected,string expectedStatus,CancellationToken ct)
 {
  try{using var response=await client.PostAsJsonAsync(route,body,CanonicalJson.SerializerOptions,ct);string json=await response.Content.ReadAsStringAsync(ct);if(!response.IsSuccessStatusCode)throw new PublicationUpstreamException((int)response.StatusCode is 502 or 503?503:409,(int)response.StatusCode is 502 or 503?"RevealCallbackUnavailable":"RevealCallbackMismatch",$"Analysis reveal {expectedStatus.ToLowerInvariant()} rejected publication: {ProblemDetail(json)}");AnalysisRevealReceipt receipt=JsonSerializer.Deserialize<AnalysisRevealReceipt>(json,CanonicalJson.SerializerOptions)??throw new PublicationUpstreamException(409,"RevealReceiptMalformed","Analysis reveal receipt was empty.");if(receipt.ScenarioId.ToString("D")!=scenarioId||receipt.RevealId!=expected.RevealId||receipt.ClonedFieldId!=expected.ClonedFieldId||receipt.AsOfUtc!=expected.ValidTimeUtc||!receipt.Status.Equals(expectedStatus,StringComparison.Ordinal)||receipt.ManifestSha256!=expected.ManifestSha256||receipt.EvidenceCount!=expected.Evidence.Count||receipt.ProductionSeriesId!=Guid.Parse(expected.ProductionSeries.SeriesId))throw new PublicationUpstreamException(409,"RevealReceiptMismatch","Analysis reveal receipt identity or content did not match the request.");using JsonDocument document=JsonDocument.Parse(json);if(PublicationJson.ContainsForbiddenProperty(document.RootElement))throw new PublicationUpstreamException(409,"RevealReceiptMalformed","Analysis reveal receipt contained unsafe data.");return CanonicalJson.Canonicalize(document.RootElement);}
  catch(PublicationUpstreamException){throw;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new PublicationUpstreamException(503,"RevealCallbackTimeout","Analysis reveal callback timed out.");}catch(JsonException e){throw new PublicationUpstreamException(409,"RevealReceiptMalformed","Analysis reveal receipt was malformed.",e);}catch(HttpRequestException e){throw new PublicationUpstreamException(503,"RevealCallbackUnavailable","Analysis reveal callback is unavailable.",e);}
 }
 static string ProblemDetail(string json){try{using JsonDocument document=JsonDocument.Parse(json);if(document.RootElement.TryGetProperty("detail",out JsonElement detail)&&detail.ValueKind==JsonValueKind.String)return (detail.GetString()??"No detail.")[..Math.Min(detail.GetString()?.Length??0,500)];}catch(JsonException){}return "No safe detail was returned.";}
}
public sealed partial class OntologyPublicationClient(IHttpClientFactory clients)
{
