   using var content=new StringContent(operation.CanonicalPayloadJson,Encoding.UTF8,"application/json");using HttpResponseMessage write=await client.PostAsync(writeRoute,content,ct);if(!write.IsSuccessStatusCode&&write.StatusCode!=HttpStatusCode.Conflict)Throw(write.StatusCode,"PublicationWriteRejected",$"{operation.TargetService} rejected staged write.");
   using HttpResponseMessage read=await client.GetAsync(operation.ReadRoute,ct);if(!read.IsSuccessStatusCode)Throw(read.StatusCode,"PublicationReadAfterWriteFailed",$"{operation.TargetService} read-after-write failed.");string actual=await read.Content.ReadAsStringAsync(ct);using JsonDocument expected=JsonDocument.Parse(operation.CanonicalPayloadJson);using JsonDocument observed=JsonDocument.Parse(actual);if(!PublicationJson.BusinessContentMatches(expected.RootElement,observed.RootElement))throw new PublicationUpstreamException(409,"PublicationReadAfterWriteMismatch",$"{operation.TargetService} persisted different business content.");
