 }
 public async Task<PublicationReconciliationReceipt> VerifyPersistedAsync(PublicationReconciliationOperation item,CancellationToken ct)
 {
  HttpClient client=clients.CreateClient(item.Operation.TargetService);try{using HttpResponseMessage read=await client.GetAsync(item.Operation.ReadRoute,ct);if(read.StatusCode==HttpStatusCode.NotFound)return new(PublicationReconciliationOutcome.Missing);if(!read.IsSuccessStatusCode)Throw(read.StatusCode,"PublicationReconciliationUnavailable",$"{item.Operation.TargetService} reconciliation read failed.");string actual=await read.Content.ReadAsStringAsync(ct);using JsonDocument observed=JsonDocument.Parse(actual);string business=PublicationJson.CanonicalBusinessContent(observed.RootElement),hash=DeterministicIdentity.Sha256(business);return hash==item.ResultHash&&business==item.ResultBusinessJson?new(PublicationReconciliationOutcome.Present,hash):new(PublicationReconciliationOutcome.Mismatch,hash);}catch(PublicationUpstreamException){throw;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new PublicationUpstreamException(503,"PublicationReconciliationTimeout","Ontology reconciliation timed out.");}catch(JsonException e){throw new PublicationUpstreamException(409,"PublicationReconciliationMismatch","Ontology reconciliation read-back was malformed.",e);}catch(HttpRequestException e){throw new PublicationUpstreamException(503,"PublicationReconciliationUnavailable","Ontology reconciliation is unavailable.",e);}
 }
 public async Task<PublicationWriteReceipt> RestoreMissingAndVerifyAsync(PublicationReconciliationOperation item,string productionEntityId,CancellationToken ct)
 {
  PublicationWriteOperation operation=item.Operation;HttpClient client=clients.CreateClient(operation.TargetService);string prefix=operation.Route[..(operation.Route.IndexOf("/api/",StringComparison.Ordinal)+4)],writeRoute=WriteRoute(operation,prefix);try{using var content=new StringContent(operation.CanonicalPayloadJson,Encoding.UTF8,"application/json");using HttpResponseMessage write=await client.PostAsync(writeRoute,content,ct);if(!write.IsSuccessStatusCode&&write.StatusCode!=HttpStatusCode.Conflict)Throw(write.StatusCode,"PublicationReconciliationWriteRejected",$"{operation.TargetService} rejected restoration.");using HttpResponseMessage read=await client.GetAsync(operation.ReadRoute,ct);if(!read.IsSuccessStatusCode)Throw(read.StatusCode,"PublicationReconciliationReadFailed",$"{operation.TargetService} restoration read-back failed.");string actual=await read.Content.ReadAsStringAsync(ct);using JsonDocument observed=JsonDocument.Parse(actual);string business=PublicationJson.CanonicalBusinessContent(observed.RootElement),hash=DeterministicIdentity.Sha256(business);if(hash!=item.ResultHash||business!=item.ResultBusinessJson)throw new PublicationUpstreamException(409,"PublicationReconciliationMismatch",$"{operation.TargetService} restored different business content.");string? productionHash=operation.EntityId==productionEntityId?PublicationJson.MonthlyProductionHash(observed.RootElement):null;return new(hash,productionHash,business);}catch(PublicationUpstreamException){throw;}catch(OperationCanceledException)when(!ct.IsCancellationRequested){throw new PublicationUpstreamException(503,"PublicationReconciliationTimeout","Ontology restoration timed out.");}catch(JsonException e){throw new PublicationUpstreamException(409,"PublicationReconciliationMismatch","Ontology restoration read-back was malformed.",e);}catch(HttpRequestException e){throw new PublicationUpstreamException(503,"PublicationReconciliationUnavailable","Ontology restoration is unavailable.",e);}
