public static class PublicationJson
{
 static readonly string[] Forbidden=["truthsample","productiontruth","stageapath","completionbinding","worldid","bindingmetadata","gridcell","ijk","oilSaturation","waterSaturation","gasSaturation","trueVerticalDepthM"];
 public static bool ContainsForbiddenProperty(JsonElement value){if(value.ValueKind==JsonValueKind.Object){foreach(var p in value.EnumerateObject()){if(Forbidden.Any(x=>p.Name.Contains(x,StringComparison.OrdinalIgnoreCase)))return true;if(ContainsForbiddenProperty(p.Value))return true;}}else if(value.ValueKind==JsonValueKind.Array)foreach(var x in value.EnumerateArray())if(ContainsForbiddenProperty(x))return true;return false;}
 public static bool BusinessContentMatches(JsonElement expected,JsonElement actual)=>BusinessContentMatches(expected,actual,null,false);
 static bool BusinessContentMatches(JsonElement expected,JsonElement actual,string? propertyName,bool surveyStation)
 {
  if(expected.ValueKind!=actual.ValueKind)return false;
  if(expected.ValueKind==JsonValueKind.Object)
  {
   if(propertyName?.Equals("ReferencePoint",StringComparison.OrdinalIgnoreCase)==true&&
      expected.EnumerateObject().Count()==2&&TryProperty(expected,"X",out var referenceNorth)&&referenceNorth.ValueKind==JsonValueKind.Number&&
      TryProperty(expected,"Y",out var referenceEast)&&referenceEast.ValueKind==JsonValueKind.Number)
    return HorizontalReferencePointMatches(referenceNorth,referenceEast,actual);
   // A newly projected tie-in is a SurveyStation too; allow only the same checked model aliases.
   // Do not reinterpret sparse legacy tie-ins that never contained the authoritative station fields.
   surveyStation=surveyStation||propertyName?.Equals("TieInPoint",StringComparison.OrdinalIgnoreCase)==true&&
    new[]{"MD","Abscissa","X","Y","TVD","Inclination","Azimuth"}.All(name=>TryProperty(expected,name,out var value)&&value.ValueKind==JsonValueKind.Number);
   var expectedProperties=expected.EnumerateObject().Where(x=>!IsServerOwned(x.Name)).ToDictionary(x=>x.Name,x=>x.Value,StringComparer.OrdinalIgnoreCase);var actualProperties=actual.EnumerateObject().Where(x=>!IsServerOwned(x.Name)).ToDictionary(x=>x.Name,x=>x.Value,StringComparer.OrdinalIgnoreCase);foreach(string name in expectedProperties.Keys.Union(actualProperties.Keys,StringComparer.OrdinalIgnoreCase)){bool hasExpected=expectedProperties.TryGetValue(name,out var expectedValue),hasActual=actualProperties.TryGetValue(name,out var actualValue);if(!hasExpected){if(actualValue.ValueKind==JsonValueKind.Null)continue;if(surveyStation&&IsDerivedStationField(name))continue;return false;}if(!hasActual){if(expectedValue.ValueKind!=JsonValueKind.Null)return false;continue;}if(!BusinessContentMatches(expectedValue,actualValue,name,false))return false;}return !surveyStation||ValidateSurveyStationEnrichment(expected,actual);
  }
  if(expected.ValueKind==JsonValueKind.Array){var e=expected.EnumerateArray().ToArray();var a=actual.EnumerateArray().ToArray();bool stationElements=propertyName?.Equals("SurveyStationList",StringComparison.OrdinalIgnoreCase)==true;return e.Length==a.Length&&e.Zip(a,(left,right)=>BusinessContentMatches(left,right,null,stationElements)).All(x=>x);}
  if(expected.ValueKind==JsonValueKind.Number)return NumbersMatch(expected,actual);
  if(expected.ValueKind==JsonValueKind.String){string? left=expected.GetString(),right=actual.GetString();if(left==right)return true;if(IsTemporalProperty(propertyName)&&TryRoundTripInstant(left,out var leftInstant)&&TryRoundTripInstant(right,out var rightInstant))return leftInstant.UtcTicks==rightInstant.UtcTicks;return TryStrictRoundTripInstant(left,out leftInstant)&&TryStrictRoundTripInstant(right,out rightInstant)&&leftInstant.UtcTicks==rightInstant.UtcTicks;}
  return expected.GetRawText()==actual.GetRawText();
 }
 static bool HorizontalReferencePointMatches(JsonElement north,JsonElement east,JsonElement actual)
 {
  if(actual.EnumerateObject().Select(x=>x.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=actual.EnumerateObject().Count())return false;
  if(!TryProperty(actual,"X",out var x)||!TryProperty(actual,"Y",out var y)||!NumbersMatch(north,x)||!NumbersMatch(east,y))return false;
  foreach(var property in actual.EnumerateObject())
  {
   if(property.Value.ValueKind==JsonValueKind.Null)continue;
   if(property.Name.Equals("X",StringComparison.OrdinalIgnoreCase)||property.Name.Equals("Y",StringComparison.OrdinalIgnoreCase))continue;
   if(property.Name.Equals("RiemannianNorth",StringComparison.OrdinalIgnoreCase)){if(!NumbersMatch(north,property.Value))return false;continue;}
   if(property.Name.Equals("RiemannianEast",StringComparison.OrdinalIgnoreCase)){if(!NumbersMatch(east,property.Value))return false;continue;}
   double bound=property.Name.Equals("Latitude",StringComparison.OrdinalIgnoreCase)?90:
    property.Name.Equals("Longitude",StringComparison.OrdinalIgnoreCase)?180:0;
   if(bound==0||property.Value.ValueKind!=JsonValueKind.Number||!property.Value.TryGetDouble(out double coordinate)||
      !double.IsFinite(coordinate)||Math.Abs(coordinate)>bound)return false;
  }
  return true;
 }
 static bool ValidateSurveyStationEnrichment(JsonElement expected,JsonElement actual)
 {
  string[] authoritative=["MD","Abscissa","X","Y","TVD","Inclination","Azimuth"];foreach(string name in authoritative)if(!TryProperty(expected,name,out var expectedValue)||!TryProperty(actual,name,out var actualValue)||expectedValue.ValueKind!=JsonValueKind.Number||actualValue.ValueKind!=JsonValueKind.Number||!NumbersMatch(expectedValue,actualValue))return false;
  if(IsActualOnly("Z",out var z)&&(!TryProperty(actual,"TVD",out var tvd)||!NumericEquivalent(z,tvd)))return false;
  if(IsActualOnly("RiemannianNorth",out var north)&&(!TryProperty(actual,"X",out var x)||!NumericEquivalent(north,x)))return false;
  if(IsActualOnly("RiemannianEast",out var east)&&(!TryProperty(actual,"Y",out var y)||!NumericEquivalent(east,y)))return false;
  if(IsActualOnly("BoreholeRadius",out var radius)&&(!TryFinite(radius,out double radiusValue)||radiusValue!=0d))return false;
  if(IsActualOnly("Latitude",out var latitude)&&(!TryFinite(latitude,out double latitudeValue)||latitudeValue < -90d||latitudeValue > 90d))return false;
  if(IsActualOnly("Longitude",out var longitude)&&(!TryFinite(longitude,out double longitudeValue)||longitudeValue < -180d||longitudeValue > 180d))return false;
  return true;
  bool IsActualOnly(string name,out JsonElement value){bool inActual=TryProperty(actual,name,out value);return inActual&&!TryProperty(expected,name,out _);}
  static bool NumericEquivalent(JsonElement left,JsonElement right)=>left.ValueKind==JsonValueKind.Number&&right.ValueKind==JsonValueKind.Number&&NumbersMatch(left,right);
  static bool TryFinite(JsonElement value,out double result){result=default;return value.ValueKind==JsonValueKind.Number&&value.TryGetDouble(out result)&&double.IsFinite(result);}
 }
 static bool IsDerivedStationField(string name)=>name.Equals("Z",StringComparison.OrdinalIgnoreCase)||name.Equals("RiemannianNorth",StringComparison.OrdinalIgnoreCase)||name.Equals("RiemannianEast",StringComparison.OrdinalIgnoreCase)||name.Equals("Latitude",StringComparison.OrdinalIgnoreCase)||name.Equals("Longitude",StringComparison.OrdinalIgnoreCase)||name.Equals("BoreholeRadius",StringComparison.OrdinalIgnoreCase);
 static bool IsTemporalProperty(string? name)=>name is not null&&(name.Equals("EffectiveAt",StringComparison.OrdinalIgnoreCase)||name.Equals("FirstSeenAt",StringComparison.OrdinalIgnoreCase)||name.EndsWith("Utc",StringComparison.OrdinalIgnoreCase)||name.Contains("TimeStart",StringComparison.OrdinalIgnoreCase)||name.Contains("TimeEnd",StringComparison.OrdinalIgnoreCase));
 static bool TryStrictRoundTripInstant(string? value,out DateTimeOffset result)=>DateTimeOffset.TryParseExact(value,"O",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind,out result);
 static bool TryRoundTripInstant(string? value,out DateTimeOffset result)=>TryStrictRoundTripInstant(value,out result)||DateTimeOffset.TryParseExact(value,"yyyy-MM-dd'T'HH:mm:ssK",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.RoundtripKind,out result);
 static bool NumbersMatch(JsonElement expected,JsonElement actual)
 {
  string left=expected.GetRawText(),right=actual.GetRawText();if(TryExactInteger(left,out decimal leftInteger)&&TryExactInteger(right,out decimal rightInteger))return leftInteger==rightInteger;if(decimal.TryParse(left,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out decimal leftDecimal)&&decimal.TryParse(right,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out decimal rightDecimal)){decimal scale=Math.Max(1m,Math.Max(Math.Abs(leftDecimal),Math.Abs(rightDecimal)));return Math.Abs(leftDecimal-rightDecimal)<=0.000000000001m*scale;}if(!double.TryParse(left,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double leftDouble)||!double.TryParse(right,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double rightDouble)||!double.IsFinite(leftDouble)||!double.IsFinite(rightDouble))return false;double tolerance=1e-12*Math.Max(1d,Math.Max(Math.Abs(leftDouble),Math.Abs(rightDouble)));return Math.Abs(leftDouble-rightDouble)<=tolerance;
  static bool TryExactInteger(string text,out decimal value){if(decimal.TryParse(text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value)&&decimal.Truncate(value)==value&&(value>=long.MinValue&&value<=long.MaxValue||value>=0&&value<=ulong.MaxValue))return true;value=0;return false;}
 }
 public static string BusinessContentHash(JsonElement value)=>DeterministicIdentity.Sha256(CanonicalBusinessContent(value));
 public static string MonthlyProductionHash(JsonElement entity){if(!TryProperty(entity,"Dataset",out var dataset)||!TryProperty(dataset,"MonthlyProduction",out var months)||months.ValueKind!=JsonValueKind.Array)throw new PublicationUpstreamException(409,"PublishedProductionMalformed","Published Well does not contain monthly production.");return BusinessContentHash(months);}
 public static string CanonicalBusinessContent(JsonElement value){using var stream=new MemoryStream();using(var writer=new Utf8JsonWriter(stream))Write(value,writer);return Encoding.UTF8.GetString(stream.ToArray());static void Write(JsonElement value,Utf8JsonWriter writer){switch(value.ValueKind){case JsonValueKind.Object:writer.WriteStartObject();foreach(var property in value.EnumerateObject().Where(x=>!IsServerOwned(x.Name)).OrderBy(x=>x.Name,StringComparer.Ordinal)){writer.WritePropertyName(property.Name);Write(property.Value,writer);}writer.WriteEndObject();break;case JsonValueKind.Array:writer.WriteStartArray();foreach(var item in value.EnumerateArray())Write(item,writer);writer.WriteEndArray();break;default:value.WriteTo(writer);break;}}}
 static bool IsServerOwned(string name)=>name.Equals("CreationDate",StringComparison.OrdinalIgnoreCase)||name.Equals("LastModificationDate",StringComparison.OrdinalIgnoreCase);
 public static bool TryProperty(JsonElement element,string name,out JsonElement value){if(element.ValueKind==JsonValueKind.Object)foreach(var p in element.EnumerateObject())if(p.Name.Equals(name,StringComparison.OrdinalIgnoreCase)){value=p.Value;return true;}value=default;return false;}
 public static void ValidateStagedPublication(PublicationStaging plan)
 {
  var groups=new Dictionary<string,IReadOnlyList<JsonElement>>(StringComparer.Ordinal);foreach(var group in plan.Operations.GroupBy(x=>x.RecordKind,StringComparer.Ordinal))groups[group.Key]=group.Select(x=>JsonDocument.Parse(x.CanonicalPayloadJson).RootElement.Clone()).ToArray();
